    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m[1],int(m[2]),int(m[3])
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()
def solve(I):
    H,W=len(I),len(I[0]); O=[r[:] for r in I]
    for i in range(H):
        for j in range(W):
            if I[i][j]==0:
                st=[(i,j)]; seen={(i,j)}; cells=[]
                while st:
                    a,b=st.pop(); cells.append((a,b))
                    for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<H and 0<=y<W and I[x][y]==0 and (x,y) not in seen:
                            seen.add((x,y)); st.append((x,y))
                rs=[c[0] for c in cells]; cs=[c[1] for c in cells]
                r0,r1,c0,c1=min(rs),max(rs),min(cs),max(cs)
                sub=[[I[r][c] for c in range(c0,c1+1)] for r in range(r0,r1+1)]
                cnt=Counter(v for row in sub for v in row)
                col=[v for v in cnt if v!=0][0]
                pts=[(r-r0,c-c0) for r in range(r0,r1+1) for c in range(c0,c1+1) if sub[r][c]==col]
                rh=max(p[0] for p in pts)+1; cw=max(p[1] for p in pts)+1
                pat={(rr,cc):col if sub[rr][cc]==col else 0 for rr in range(rh) for cc in range(cw)}
                for r in range(r0,r1+1):
                    for c in range(c0,c1+1):
                        O[r][c]=pat[((r-r0)%rh)][((c-c0)%cw)]
    return O
for k in ['Demo pair 1','Demo pair 2']:
    print(k,'match:',solve(G[k+' input'])==G[k+' output'])
print(json.dumps(solve(G['Test input'])))

